import{esc,input,select,button}from'../phase4/ui.js';
import{rate,number,branchValues}from'./b22-model.js';
const btn=(a,l,x='')=>button('p22-'+a,l,x),f=(k,l,v)=>input(k,l,v).replace('maxlength="2000"','maxlength="1500"'),sel=(k,l,v,o)=>select(k,l,v,o),note=s=>`<p class="b22-note">${s}</p>`,card=s=>`<div class="b22-card">${s}</div>`,fields=s=>`<div class="b22-fields">${s}</div>`,fmt=n=>Number.isFinite(n)?String(Math.round(n*1000)/1000):'—';
const table=(h,rows)=>`<table class="b22-table"><thead><tr>${h.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
const qfields=(t,m)=>(t.questions||[]).map((q,i)=>q.options?sel('answers.'+i,q.label,m.answers[i],q.options):f('answers.'+i,q.label,m.answers[i])).join('');
const groupColor=g=>g==='红'?'red':g==='蓝'?'blue':g==='黑'?'black':g==='A'?'a':'';
const labelEvent={both:'两边都有',either:'至少一边',notA:'不属于A'};
const fold=(html,yes)=>yes?`<details class="b22-fold"><summary>查看或修改刚才的操作</summary>${html}</details>`:html;
const countOf=(arr,n)=>Array.from({length:n},(_,i)=>arr.filter(v=>v===i).length);
function pick(t,b){return`<div class="b22-tiles ${t.items.length>20?'compact':''}">${t.items.map((v,i)=>btn('toggle',esc(v.label),`data-index="${i}" class="${groupColor(v.group)} ${b.selected.includes(i)?'on':''}" aria-pressed="${b.selected.includes(i)}"`)).join('')}</div>`+note(`已圈 ${b.selected.length} 个 · 总共 ${t.items.length} 个。每个小格代表一个等可能结果。`);}
function ordered(t,b){return card(`<b>从小到大排成一队</b><div class="b22-order">${b.order.length?b.order.map(i=>`<span>${esc(t.cards[i].label)}</span>`).join(' → '):'<span class="empty">从下面挑第一张</span>'}</div>${b.order.length===t.cards.length&&b.order.every((n,i)=>!i||t.cards[b.order[i-1]].p<=t.cards[n].p)?`<svg class="b22-graph b22-numberline" viewBox="0 0 700 90" role="img" aria-label="按真实概率在0到1数轴标出这些机会"><line x1="60" y1="35" x2="640" y2="35" stroke="#91a699" stroke-width="2"/>${t.cards.map(c=>`<circle cx="${60+580*c.p}" cy="35" r="6" fill="#6c9d88"/><text x="${60+580*c.p}" y="65" text-anchor="middle">${fmt(c.p)}</text>`).join('')}<text x="60" y="85" text-anchor="middle">不可能</text><text x="640" y="85" text-anchor="middle">一定</text></svg>`:'<small>排好后，再看这些机会在0到1之间的位置。</small>'}`)+(t.sampleBags?card(`<b>实际试验 · 每次抽后放回</b><p>甲袋：${b.drawA?`50次，红${b.drawA.filter(x=>x===0).length}次`:'还没抽'}　乙袋：${b.drawB?`50次，红${b.drawB.filter(x=>x===0).length}次`:'还没抽'}</p><small>这是两份实际模拟结果，可能上下波动，规则中的3/4和6/12没有改变。</small>`):'');}
function trials(t,b){const n=b.draws.length,c=countOf(b.draws,t.labels.length),target=t.labels[t.event];let s=card(`<b>${t.hidden?'模拟装置：内部规则暂时藏起来':'每次都按同一规则进行'}</b><p>已试 ${n} 次${t.theory?' · 模型给出的机会 '+esc(t.theory):''}</p>${n?`<p>${esc(target)}出现 ${c[t.event]} 次 · 这次比例 ${c[t.event]}/${n} ≈ ${fmt(c[t.event]/n*100)}%</p>`:''}`);
 if(n){s+=table(['结果','实际次数'],t.labels.map((x,i)=>[x,c[i]]));if(t.labels.length===6)s+=note('公平骰子每个面在60次中预期约10次，在600次中预期约100次；实际不必恰好相同。');if(b.checkpoints.length>1)s+=table(['记录时的总次数',`${target}的次数`,`${target}的比例`],b.checkpoints.map(k=>{const hits=b.draws.slice(0,k).filter(x=>x===t.event).length;return[k,hits,fmt(hits/k*100)+'%'];}));s+=`<details class="b22-fold"><summary>查看${n}次真实模拟结果</summary><div class="b22-log">${b.draws.map((x,i)=>`<span title="第${i+1}次">${esc(t.labels[x])}</span>`).join('')}</div></details>`;}
 return s;
}
function mapped(t,b){let s=card(`<b>十个等可能数字</b><p>选中代表A的数字；每一次一直读到第一次出现A。</p><div class="b22-tiles">${Array.from({length:10},(_,i)=>btn('toggle',String(i),`data-index="${i}" class="${b.selected.includes(i)?'on':''}" aria-pressed="${b.selected.includes(i)}"`)).join('')}</div><small>已选 ${b.selected.length} 个数字；一行数字代表一次完整模拟。</small>`);
 if(t.given)s+=note(`给定的两组记录：50次中${t.given[0]}次，另一组50次中${t.given[1]}次。`);
 if(b.runs.length){const wins=b.runs.filter(r=>r.length>=4).length;s+=card(`<b>已完成 ${b.runs.length}/${t.targetRuns} 次</b><p>至少4个数字才遇到A：${wins} 次</p><small>这次记录中的比例是 ${wins}/${b.runs.length} ≈ ${fmt(wins/b.runs.length*100)}%。每一行最后一个数字才是A。</small>`)+`<details class="b22-fold"><summary>查看每次实际生成的数字</summary><div class="b22-runlog">${b.runs.map((r,i)=>`<p><b>${i+1}</b> ${r.map((n,j)=>`<span class="${j===r.length-1?'hit':''}">${n}</span>`).join(' ')}</p>`).join('')}</div></details>`;}
 if(b.pending.length)s+=note('本次还没有出现A，已保留前面的数字；继续生成。');return s;
}
function partitions(t,b){const sum=t.weights.reduce((x,n)=>x+n,0),rows=t.labels.map((l,i)=>[l,t.weights[i],b.built?.[i]===null||!b.built?'待放':fmt(b.built[i])]);let s=card(`<b>把每一份放回整体</b><p>原记录：${t.labels.map((l,i)=>esc(l)+' '+t.weights[i]).join('，')}；总计 ${sum}。</p>${t.given?`<p>${esc(t.given)}</p>`:''}`)+table(['结果','份数 / 次数','你放进去的概率'],rows);
 if(b.built&&b.built.every(v=>v!==null&&v>=0)){const total=b.built.reduce((x,n)=>x+n,0),scale=Math.max(1,total),colors=['#9eb5c3','#dfa77e','#d8c783','#a3bb9e'];let x=45,svg='';for(const[v,i]of b.built.map((v,i)=>[v,i])){const w=600*v/scale;svg+=`<rect x="${x}" y="40" width="${w}" height="44" fill="${colors[i%4]}"/>`;x+=w;}svg+=`<line x1="${45+600/scale}" y1="26" x2="${45+600/scale}" y2="100" stroke="#536353" stroke-width="2"/><text x="45" y="120">0</text><text x="${45+600/scale}" y="120" text-anchor="middle">1</text>`;s+=`<svg class="b22-graph" viewBox="0 0 700 140" role="img" aria-label="当前概率各份拼成的长条，总和${fmt(total)}">${svg}</svg>`+note(`当前各份合起来 ${fmt(total)}；标记的1代表完整的一份。`);}
 return s;
}
function draws(b){return card(`<b>开始：3红2蓝</b><div class="b22-bag">🔴 🔴 🔴　🔵 🔵</div><p>先假设第一次拿到：${b.firstColor==='red'?'红珠':b.firstColor==='blue'?'蓝珠':'还没选'}。</p>`)+(b.observed.length?table(['情形','接下来袋里剩下','再次抽红的机会'],b.observed.map(x=>[(x.first==='red'?'先拿红，':'先拿蓝，')+(x.mode==='return'?'放回':'不放回'),`${x.red}红、${x.blue}蓝`,`${x.red}/${x.red+x.blue}`])):'');}
function grid(t,b){return`<div class="b22-grid-wrap"><table class="b22-grid"><thead><tr><th>第一次＼第二次</th>${t.cols.map(v=>`<th>${esc(v)}</th>`).join('')}</tr></thead><tbody>${t.rows.map((row,i)=>`<tr><th>${esc(row)}</th>${t.cols.map((col,j)=>{const k=i*t.cols.length+j;return`<td>${b.rows.includes(i)?btn('toggle',esc(row)+' / '+esc(col),`data-index="${k}" class="${b.selected.includes(k)?'on':''}" aria-pressed="${b.selected.includes(k)}"`):'<span>待搭</span>'}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`+note(`已搭 ${b.rows.length}/${t.rows.length} 行 · 圈出 ${b.selected.length} 个结果。行与列的位置分别表示第一次和第二次。`);}
function venn(t,b){let counts;if(t.mode==='items')counts=[0,1,2,3].map(r=>b.assigned.filter(x=>x===r).length);else counts=b.built||[null,null,null,null];const masks=b.selected||[],v=i=>counts[i]===null?'?':counts[i],on=i=>masks.includes(i)?'#90b8a5':'transparent';
 return`<svg class="b22-venn" viewBox="0 0 700 300" role="img" aria-label="两圈与圈外，共四个区域"><defs><mask id="vna"><rect width="700" height="300" fill="white"/><circle cx="405" cy="150" r="104" fill="black"/></mask><mask id="vnb"><rect width="700" height="300" fill="white"/><circle cx="295" cy="150" r="104" fill="black"/></mask><clipPath id="vni"><circle cx="295" cy="150" r="104"/></clipPath><mask id="vno"><rect width="700" height="300" fill="white"/><circle cx="295" cy="150" r="104" fill="black"/><circle cx="405" cy="150" r="104" fill="black"/></mask></defs><rect x="50" y="25" width="600" height="250" rx="15" fill="#f7f7ef" stroke="#b8c8b8"/><rect x="50" y="25" width="600" height="250" rx="15" fill="${on(3)}" mask="url(#vno)"/><circle cx="295" cy="150" r="104" fill="#a9c3d0" opacity=".25" stroke="#6f94a7" stroke-width="2"/><circle cx="405" cy="150" r="104" fill="#d9b499" opacity=".25" stroke="#b78362" stroke-width="2"/><circle cx="295" cy="150" r="103" fill="${on(0)}" mask="url(#vna)"/><circle cx="405" cy="150" r="103" fill="${on(2)}" mask="url(#vnb)"/><circle cx="405" cy="150" r="103" fill="${on(1)}" clip-path="url(#vni)"/><g fill="#344d43" text-anchor="middle" font-size="16"><text x="245" y="39">${esc(t.labels[0])}</text><text x="455" y="39">${esc(t.labels[1])}</text><text x="230" y="155">${v(0)}</text><text x="350" y="155">${v(1)}</text><text x="470" y="155">${v(2)}</text><text x="595" y="155">${v(3)}</text><text x="595" y="180" font-size="12">两边都没有</text></g></svg>`+note('左边独有 · 两边都有 · 右边独有 · 两边都没有：每份只放一次。');
}
function branches(t,b){const names=['红→红','红→蓝','蓝→红','蓝→蓝'];const lines=names.map((name,i)=>{const p=b.paths.find(v=>v.index===i),y=30+i*58;return`<line x1="100" y1="118" x2="310" y2="${i<2?55:200}" stroke="#8eaa9d" stroke-width="2"/><line x1="310" y1="${i<2?55:200}" x2="535" y2="${y}" stroke="${p?'#648c78':'#cdd8cf'}" stroke-width="${p?4:2}"/><text x="545" y="${y+5}">${name} ${p?`${esc(p.first)} × ${esc(p.second)}`:'待搭'}</text>`;}).join('');return card('原袋：3红2蓝。假设第一次的颜色，再数剩余的珠子。')+`<svg class="b22-graph" viewBox="0 0 700 250" role="img" aria-label="两次取珠构成四条路径">${lines}</svg>`;}
export function visual(t,m){const b=m.board;let v='';
 if(t.type==='x-p22-pick')v=pick(t,b);
 if(t.type==='x-p22-order')v=ordered(t,b);
 if(t.type==='x-p22-experiment')v=trials(t,b);
 if(t.type==='x-p22-mapping')v=mapped(t,b);
 if(t.type==='x-p22-table')v=partitions(t,b);
 if(t.type==='x-p22-draw')v=draws(b);
 if(t.type==='x-p22-grid')v=grid(t,b);
 if(t.type==='x-p22-venn'){if(t.mode==='counts')v=card(`<b>给定的模拟记录</b><p>${esc(t.labels[0])} ${t.totals[0]}份 · ${esc(t.labels[1])} ${t.totals[1]}份 · 两边都有 ${t.totals[2]}份 · 一共 ${t.totals[3]}份。</p>`);v+=venn(t,b);if(t.mode==='items')v+=card('原来的数字卡：'+t.items.join('、')+'。已放 '+b.assigned.filter(x=>x!==null).length+'/'+t.items.length+' 张。')+table(['只在A','两边都有','只在B','都没有'],[[0,1,2,3].map(k=>t.items.filter((_,i)=>b.assigned[i]===k).join('、')||'—')]);if(t.mode==='shade')v+=note('正在标：'+(labelEvent[b.event]||'还没选择')+'；已留下：'+Object.keys(b.shades).map(x=>labelEvent[x]).join('、'));}
 if(t.type==='x-p22-branch')v=branches(t,b);
 if(t.type==='x-p22-sort')v=card(`<b>第${Math.min(b.cursor+1,t.items.length)}/${t.items.length}对</b><p>${esc(t.items[Math.min(b.cursor,t.items.length-1)][0])}</p><small>已放好${b.cursor}对。</small>`);
 return`<div class="b22-world">${note('动一动，留下自己的发现')}${v}</div>`;
}
export function controls(t,m){const b=m.board;let v='',ready=true;
 if(t.type==='x-p22-pick'){v+=(t.groupAction?btn('group','圈出 / 清除全部'+esc(t.groupAction)):'')+sel('kind','每个小格被选中的机会',m.kind,[['equal','一样大（题目已说明）'],['unknown','不知道或不一样']])+f('prob','圈出的结果占全部多少（可写分数）',m.prob);}
 if(t.type==='x-p22-order'){if(t.sampleBags){v+=!b.started?sel('guess','先猜哪袋更容易抽到红',m.guess,[['a','甲袋'],['b','乙袋'],['same','一样'],['unknown','还不确定']])+btn('start','保留猜想'):(b.drawA?'':btn('sample','甲袋抽50次，每次放回','data-index="0"'))+(b.drawB?'':btn('sample','乙袋抽50次，每次放回','data-index="1"'));}v+=fold(`<div class="b22-pick">${t.cards.map((c,i)=>btn('put',esc(c.label),`data-index="${i}" ${b.order.includes(i)?'disabled':''}`)).join('')}</div>${btn('undo','退回最后一张')}`,b.order.length===t.cards.length);ready=b.order.length===t.cards.length&&(!t.sampleBags||b.drawA&&b.drawB);}
 if(t.type==='x-p22-experiment'){v=!b.started?sel('guess','先猜这一次目标结果会怎样',m.guess,[['more','可能多一些'],['less','可能少一些'],['equal','可能刚好一样'],['unknown','还不确定']])+btn('start','保留猜想'):b.checkpoints.length<t.targets.length?btn('run',`继续试 ${t.targets[b.checkpoints.length]-b.draws.length} 次`):note('这些结果都已留下。');ready=b.checkpoints.length===t.targets.length;if(ready)v+=f('rate',`这次“${t.labels[t.event]}”出现的比例（次数/总次数）`,m.rate)+(t.expected?f('expected','公平模型中600次预期出现几次',m.expected):'');}
 if(t.type==='x-p22-mapping'){v=b.runs.length<t.targetRuns?btn('run',`继续生成最多10次（已完成${b.runs.length}次）`):note('这几次都记录好了。');ready=b.runs.length===t.targetRuns&&!b.pending.length;if(ready)v+=f('rate','这次至少需要4个数字的比例（次数/总次数）',m.rate);}
 if(t.type==='x-p22-table'){v=fields(t.labels.map((l,i)=>f('values.'+i,`${l}占整份多少（可写分数）`,m.values[i])).join(''))+btn('build','把这些份拼到一起');}
 if(t.type==='x-p22-draw'){v=sel('first','假设第一次拿到',m.first,[['red','红珠'],['blue','蓝珠']])+btn('choose','拿出这一颗')+(b.firstColor?sel('choice','第一颗怎样处理',m.choice,[['return','放回原袋'],['keep','不放回']])+btn('observe','观察第二次还剩什么'):'');ready=b.observed.some(x=>x.first==='red'&&x.mode==='return')&&b.observed.some(x=>x.first==='red'&&x.mode==='keep');}
 if(t.type==='x-p22-grid'){v=fold(`<div class="b22-pick">${t.rows.map((r,i)=>btn('row',`搭出第${esc(r)}行`, `data-index="${i}" ${b.rows.includes(i)?'disabled':''}`)).join('')}</div>`,b.rows.length===t.rows.length);ready=b.rows.length===t.rows.length;v+=ready?f('prob','圈出的结果占全部多少（可写分数）',m.prob):'';}
 if(t.type==='x-p22-venn'){
  if(t.mode==='items'){v=sel('item','选择一张数字卡',m.item,t.items.map((n,i)=>[String(i),'数字'+String(n)]))+sel('region','放到哪一块',m.region,[['0','只在A'],['1','两边都有'],['2','只在B'],['3','两边都没有']])+btn('place','放好这张卡');ready=b.assigned.every(x=>x!==null);}
  if(t.mode==='counts')v=fold(fields(['只在左边','两边都有','只在右边','两边都没有'].map((l,i)=>f('values.'+i,l+'有几份',m.values[i])).join(''))+btn('build','把这四块拼出来'),!!b.built&&b.built.every((v,i)=>v===t.counts[i]));
  if(t.mode==='shade'){v=sel('event','要标出哪一种',m.event,t.events.map(e=>[e,labelEvent[e]]))+btn('activate','开始标这句话');if(b.event)v+=`<div class="b22-pick">${['只在A','两边都有','只在B','两边都没有'].map((l,i)=>btn('shade',l,`data-index="${i}" class="${b.selected.includes(i)?'on':''}"`)).join('')}</div>`+btn('save','留下这一种涂法');ready=t.events.every(e=>b.shades[e]);}
 }
 if(t.type==='x-p22-branch'){v=fold(fields(f('first','第一次选到这种颜色的机会',m.first)+f('second','在这条路上第二次的机会',m.second))+`<div class="b22-pick">${['红→红','红→蓝','蓝→红','蓝→蓝'].map((l,i)=>btn('branch','搭 '+l,`data-index="${i}"`)).join('')}</div>`,b.paths.length===4);ready=b.paths.length===4;if(ready)v+=f('prob','红后再红：把这条路上两次机会相乘',m.prob);}
 if(t.type==='x-p22-sort'){v=b.cursor<t.items.length?sel('choice','这一对的关系',m.choice,[['independent','前一次不改变下一次机会'],['dependent','前一次改变下一次条件']])+btn('classify','把这一对放好'):note('五对都已放好。');ready=b.cursor===t.items.length;}
 if(ready)v+=qfields(t,m);if(m.issue)v+=`<p role="status" class="b22-issue">${esc(m.issue)}</p>`;
 return`<div class="b22-controls">${v}<details class="b22-fold"><summary>用自己的话留下发现（可选）</summary>${f('prose','我的解释或新问题',m.prose)}<small>原话会保存，暂不自动判断这段解释。</small></details></div>`;
}
export const render=(t,m)=>`<div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}</div>`;
